import sys
p = sys.argv[1]
s = open(p, encoding="utf-8").read()


def rep(old, new, n=1):
    global s
    assert s.count(old) == n, (s.count(old), old[:90])
    s = s.replace(old, new)


i = s.index('function renderVerdict(d,c,v,ps){')
j = s.index('function buildRail(){')
s = s[:i] + r'''var SUM={};
function renderVerdict(d){
