  var db=ps.filter(function(p){return p.failure_class==="docs_bug"}),proven=v&&v.status==="verified";
  var pr=evAll(d).filter(function(e){return e.kind==="pr"&&e.url&&safeUrl(e.url)});
  var head,detail="",tone="ok";
  if(db.length&&pr.length){head=plural(db.length,"docs bug")+" found and fixed.";detail="Step "+db[0].step_id+": "+clip(db[0].reason||db[0].old_command,170);tone="bad"}
  else if(db.length){head="FirstRun flagged "+plural(db.length,"docs bug")+".";detail="Step "+db[0].step_id+": "+clip(db[0].reason||db[0].old_command,170);tone="bad"}
  else if(ps.length){head="The steps run once the container has "+plural(ps.length,"setup fix","setup fixes")+".";detail=clip(ps[0].reason,170)}
  else if(gu.length){head="Step "+(gu[0].step_id!=null?gu[0].step_id:"")+" failed, and FirstRun could not fix it.";detail=clip(gu[0].reason||gu[0].error||"",170);tone="bad"}
  else if(c.bad){head=plural(c.bad,"step")+" failed.";tone="bad"}
  else if(c.skip){head="Every step FirstRun could run passes.";detail=plural(c.skip,"step")+" skipped and not tested."}
  else head="The quickstart works as written.";
  if(S.ex&&SUM[S.ex])detail=SUM[S.ex];
  var prf=proven?"Proven: "+v.steps_passed+" of "+v.steps_total+" steps pass in a fresh container.":(ps.length?"Not yet proven in a fresh container.":"");
  var t=el("div","vd-t "+tone);t.appendChild(el("b",null,head));if(prf)t.appendChild(el("span",null," "+prf));V.appendChild(t);
  if(detail)V.appendChild(el("p","vd-d",detail));
  var act;
  if(pr.length){act=ext(pr[0].url,"Review the pull request"+((pr[0].label||"").match(/#\d+/)?" "+pr[0].label.match(/#\d+/)[0]:""),"vd-a")}
  else if(ps.length||gu.length){act=el("button","vd-a","See the fix");act.type="button";act.addEventListener("click",function(){var i=S.st.findIndex(function(m){return m.id==="fix"});if(i>=0)go(i,true)})}
  if(act)V.appendChild(act);
}
''' + s[j:]
